{
  "interpretation": {
    "name": "TightenVariantFastenersLine2",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, then return the tool to the crib and release it for the other lines.",
    "constraints": [
      "The tool NR7 must be reserved before any use and the lease renewed with the reservation token before every physical use (E1, E6)",
      "The tool must be at the station before configure-tool and tighten-fasteners (E3)",
      "transport-tool must be delegated to the Executor agvexecutor (E2)",
      "The tightening program must come from get-program; no torque or tolerance literals in the Recipe (E4)",
      "The tightening must be evaluated and recorded (E5)",
      "The tool must be returned to the crib and released after use so other lines are not blocked",
      "Every single tool-using Step must be shorter than the 120 s lease (E9)"
    ],
    "preference": "Release the tool as early as possible",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-f30-tightening-with-tool-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
